  'thread.latest': { args: { addrs: string[] }; value: AppThreadLatest }
  'thread.send': { args: { addr: string; text: string; via?: string }; value: AppThreadPosted }
  'thread.answerCard': { args: { addr: string; answer?: string; cardId: string; confirm?: boolean; delivery?: string; hosts?: string[]; scope?: string; secret?: string }; value: AppCardAnswered }
  'thread.voidCard': { args: { addr: string; cardId: string }; value: AppCardVoided }
  'thread.events': { args: { conversation: string }; value: AppThreadItem }
  'thread.ensurePinned': { args: { workspace: string }; value: AppPinnedChat }
  'files.list': { args: { relPath: string; showHidden?: boolean; workspace: string }; value: AppFileEntry[] }
  'files.read': { args: { relPath: string; workspace: string }; value: AppFileText }
  'files.readBinary': { args: { relPath: string; workspace: string }; value: AppFileBase64 }
  'files.readRange': { args: { len?: number; offset?: number; relPath: string; workspace: string }; value: AppFileRange }
  'files.write': { args: { content: string; relPath: string; workspace: string }; value: AppFileDone }
  'files.uploadBinary': { args: { base64: string; dir: string; filename: string; workspace: string }; value: AppFileLanded }
  'files.uploadChunk': { args: { base64?: string; dir: string; filename: string; isLast?: boolean; offset?: number; status?: boolean; totalBytes?: number; uploadId: string; workspace: string }; value: AppFileChunk }
  'files.create': { args: { isDirectory?: boolean; relPath: string; workspace: string }; value: AppFileDone }
  'files.copy': { args: { destination: string; sources: string[]; workspace: string }; value: AppFileDone }
  'files.move': { args: { destination: string; sources: string[]; workspace: string }; value: AppFileDone }
  'files.rename': { args: { newName: string; relPath: string; workspace: string }; value: AppFileLanded }
  'files.events': { args: { workspace: string }; value: AppFsFrame }
  'resources.list': { args: { workspace: string }; value: AppResources }
  'resources.add': { args: { relPath: string; workspace: string }; value: AppResourceAdded }
  'resources.remove': { args: { relPath: string; workspace: string }; value: AppResourceRemoved }
  'tickets.list': { args: { all?: boolean; project: string; status?: string }; value: AppTickets }
  'tickets.show': { args: { brief?: boolean; id: string }; value: AppTicketDetail }
  'tickets.create': { args: { agentName?: string; assignees?: string[]; body?: string; briefHtml?: string; kind?: string; options?: string[]; priority?: number; project: string; title: string }; value: AppTicketCreated }
  'tickets.comment': { args: { body: string; id: string; optionPick?: boolean }; value: AppTicketCommented }
  'tickets.answer': { args: { answer: string; id: string }; value: AppTicketAnswered }
  'tickets.resolve': { args: { id: string; status?: string }; value: AppTicketStatus }
  'tickets.assign': { args: { id: string; usernames: string[] }; value: AppTicketAssigned }
  'wiki.index': { args: { project: string }; value: AppWikiIndex }
  'wiki.note': { args: { id: string; project: string }; value: AppWikiNote }
  'storeDocs.collections': { args: { workspace: string }; value: AppStoreCollections }
  'storeDocs.get': { args: { id: string; name: string; workspace: string }; value: AppStoreDoc }
  'storeDocs.query': { args: { limit?: number; name: string; workspace: string }; value: AppStoreDocs }
  'db.tables': { args: { workspace: string }; value: AppDbTables }
  'db.rows': { args: { id?: string; limit?: number; table: string; workspace: string }; value: AppDbRows }
  'db.insert': { args: { row: Record<string, unknown>; table: string; workspace: string }; value: AppDbRow }
  'db.update': { args: { id: string; row: Record<string, unknown>; table: string; workspace: string }; value: AppDbRow }
  'db.delete': { args: { id: string; table: string; workspace: string }; value: AppDbRow }
  'db.query': { args: { params?: unknown[]; sql: string; workspace: string }; value: AppDbQuery }
  'heartbeats.list': { args: { workspace: string }; value: AppHeartbeat[] }
  'heartbeats.show': { args: { name: string; workspace: string }; value: AppHeartbeatDetail }
  'heartbeats.status': { args: { limit?: number; name: string; workspace: string }; value: AppHeartbeatFire[] }
  'heartbeats.fires': { args: { limit?: number; workspace: string }; value: AppHeartbeatFire[] }
  'heartbeats.add': { args: { frequency: string; instructions: string; name: string; spec?: Record<string, unknown>; workspace: string }; value: AppHeartbeat }
  'heartbeats.edit': { args: { frequency?: string; instructions?: string; name: string; spec?: Record<string, unknown>; workspace: string }; value: AppHeartbeat }
  'heartbeats.enable': { args: { enabled: boolean; name: string; workspace: string }; value: AppHeartbeat }
  'heartbeats.rename': { args: { from: string; to: string; workspace: string }; value: AppHeartbeat }
  'heartbeats.archive': { args: { name: string; workspace: string }; value: AppHeartbeatArchived }
  'heartbeats.fire': { args: { name: string; workspace: string }; value: AppHeartbeatFired }
